{ "appendquerystring": false, "associatecurrentportaluser": false, "attachfile": false, "attachfileallowmultiple": false, "attachfilelabel": "[{"LCID":1033,"Value":""}]", "attachfilerequired": false, "attachfilerestrictaccept": false, "autogeneratesteps": false, "captcharequired": false, "entityname": "new_timesheet", "entitypermissionsenabled": true, "entitysourcetype": 0, "forceallfieldsrequired": false, "formname": "Portal", "geolocation_displaymap": false, "geolocation_enabled": false, "geolocation_maptype": 756150000, "hideformonsuccess": true, "mode": 100000000, "onsuccess": 756150000, "populatereferenceentitylookupfield": false, "portaluserlookupattributeisactivityparty": false, "recommendedfieldsrequired": true, "recordsourceallowcreateonnull": false, "redirecturlappendentityidquerystring": false, "redirectwebpage": null, "referenceentityshowreadonlyform": false, "referencequerystringisprimarykey": true, "registerstartupscript": "$(document).ready(function () {
 console.log('Period Validation Script Loaded.');

 function getCurrentTimesheetId() {
 const url = new URL(document.referrer);
 const params = new URLSearchParams(url.search);
 return params.get('assignmentid');
 }

 const assignmentId = getCurrentTimesheetId(); 
 console.log(`Current Timesheet ID: ${assignmentId}`);

 // Get references to the form fields using jQuery
 var $periodStartField = $('#new_periodstart_datepicker_description');
 var $periodEndField = $('#new_periodend_datepicker_description');
 var $insertButton = $('#InsertButton'); // Submit button

 // Disable the submit button initially
 if ($insertButton.length) {
 $insertButton.prop('disabled', true);
 console.log('InsertButton has been disabled initially.');
 } else {
 console.error('InsertButton not found.');
 }

 function getTimesheetTypeFromLocalStorage(assignmentId) {
 var placementsData = JSON.parse(localStorage.getItem("placements")) || {};
 var timesheetData = placementsData[assignmentId] || {};

 var timesheetTypeValue = timesheetData.timesheetTypeValue;
 var timesheetTypeLabel = timesheetData.timesheetTypeLabel;

 if (!timesheetTypeValue || !timesheetTypeLabel) {
 console.warn(`No timesheet data found in localStorage for assignment ${assignmentId}.`);
 } else {
 console.log(`Retrieved from localStorage for assignment ${assignmentId} - timesheetTypeValue: ${timesheetTypeValue}, timesheetTypeLabel: ${timesheetTypeLabel}`);
 }

 return { timesheetTypeValue, timesheetTypeLabel };
 }

 function parseDate(dateString) {
 var parts = dateString.split('/');
 if (parts.length !== 3) return null;
 var day = parseInt(parts[0], 10);
 var month = parseInt(parts[1], 10) - 1;
 var year = parseInt(parts[2], 10);
 var date = new Date(year, month, day);
 return isNaN(date.getTime()) ? null : date;
 }

 function formatDate(date) {
 var day = String(date.getDate()).padStart(2, '0');
 var month = String(date.getMonth() + 1).padStart(2, '0'); // Months are 0-based in JS
 var year = date.getFullYear();
 return `${day}/${month}/${year}`;
 }

 // Helper function to check if the difference is approximately one month
 function isOneMonthDifference(startDate, endDate) {
 var startYear = startDate.getFullYear();
 var startMonth = startDate.getMonth();
 var startDay = startDate.getDate();

 var endYear = endDate.getFullYear();
 var endMonth = endDate.getMonth();
 var endDay = endDate.getDate();

 // Calculate the difference in months
 var months = (endYear - startYear) * 12 + (endMonth - startMonth);

 // Check if the difference is exactly one month
 if (months === 1) {
 if (startDay === endDay) {
 return true;
 } else {
 var lastDayOfStartMonth = new Date(startYear, startMonth + 1, 0).getDate();
 var lastDayOfEndMonth = new Date(endYear, endMonth + 1, 0).getDate();
 if (startDay === lastDayOfStartMonth && endDay === lastDayOfEndMonth) {
 return true;
 }
 }
 }
 return false;
 }

 // Function to display an error message under the closest tr of the Period End field
 function displayErrorMessage(message) {
 var $errorRow = $('#periodErrorMessage');

 if ($errorRow.length === 0) {
 $errorRow = $('<tr>', { id: 'periodErrorMessage' }).css({ color: 'red', fontSize: '12px', marginTop: '5px' });
 var $closestTr = $periodEndField.closest('tr');
 var $errorCell = $('<td>', { colspan: 1, text: message }).css({ color: 'red', fontSize: '12px', padding: '10px 0 10px 28px' });
 $errorRow.append($errorCell);
 $closestTr.after($errorRow);
 } else {
 $errorRow.find('td').text(message);
 }
 }

 function removeErrorMessage() {
 var $errorRow = $('#periodErrorMessage');
 if ($errorRow.length) $errorRow.remove();
 }

 function disableInsertButton() {
 if ($insertButton.length) $insertButton.prop('disabled', true);
 }

 function enableInsertButton() {
 if ($insertButton.length) $insertButton.prop('disabled', false);
 }

 function validatePeriod() {
 var { timesheetTypeValue, timesheetTypeLabel } = getTimesheetTypeFromLocalStorage(assignmentId);
 if (!timesheetTypeLabel) {
 displayErrorMessage("Timesheet type data is missing.");
 disableInsertButton();
 return;
 }

 var periodStartDate = parseDate($periodStartField.val());
 var periodEndDate = parseDate($periodEndField.val());

 if (!periodStartDate && !periodEndDate) {
 displayErrorMessage('Please select Period Start and Period End values.');
 disableInsertButton();
 return;
 }

 // Suggest Period End based on Period Start if applicable
 if (periodStartDate && !periodEndDate) {
 let suggestedEndDate;
 if (timesheetTypeLabel.toLowerCase() === 'weekly') {
 suggestedEndDate = new Date(periodStartDate);
 suggestedEndDate.setDate(suggestedEndDate.getDate() + 6);
 } else if (timesheetTypeLabel.toLowerCase() === 'monthly') {
 suggestedEndDate = new Date(periodStartDate);
 suggestedEndDate.setMonth(suggestedEndDate.getMonth() + 1);
 }
 displayErrorMessage(`Suggested Period End: ${formatDate(suggestedEndDate)}`);
 disableInsertButton();
 return;
 }

 // Suggest Period Start based on Period End if applicable
 if (!periodStartDate && periodEndDate) {
 let suggestedStartDate;
 if (timesheetTypeLabel.toLowerCase() === 'weekly') {
 suggestedStartDate = new Date(periodEndDate);
 suggestedStartDate.setDate(suggestedStartDate.getDate() - 6);
 } else if (timesheetTypeLabel.toLowerCase() === 'monthly') {
 suggestedStartDate = new Date(periodEndDate);
 suggestedStartDate.setMonth(suggestedStartDate.getMonth() - 1);
 }
 displayErrorMessage(`Suggested Period Start: ${formatDate(suggestedStartDate)}`);
 disableInsertButton();
 return;
 }

 // Proceed with validation if both dates are present
 var dayDifference = Math.ceil((periodEndDate - periodStartDate) / (1000 * 3600 * 24));
 var isValid = false;
 var errorMessage = '';

 if (timesheetTypeLabel.toLowerCase() === 'weekly') {
 if (dayDifference === 6) {
 isValid = true;
 } else {
 errorMessage = 'The timesheet period should be within a week (7 days).';
 }
 } else if (timesheetTypeLabel.toLowerCase() === 'monthly') {
 if (isOneMonthDifference(periodStartDate, periodEndDate)) {
 isValid = true;
 } else {
 errorMessage = 'The timesheet period should be within one month.';
 }
 }

 if (!isValid) {
 displayErrorMessage(errorMessage);
 disableInsertButton();
 } else {
 removeErrorMessage();
 enableInsertButton();
 }
 }

 let lastStartValue = $periodStartField.val();
 let lastEndValue = $periodEndField.val();

 setInterval(function() {
 if ($periodStartField.val() !== lastStartValue || $periodEndField.val() !== lastEndValue) {
 lastStartValue = $periodStartField.val();
 lastEndValue = $periodEndField.val();
 validatePeriod();
 }
 }, 500);

 $periodStartField.on('input change blur', validatePeriod);
 $periodEndField.on('input change blur', validatePeriod);

 validatePeriod();
});
